#!/bin/sh
# Regenerate vendor/willbooster-tree-sitter (the `cccc-willbooster-tree-sitter`
# crate) from a `willbooster-tree-sitter` release on crates.io.
#
# Usage: vendor-willbooster-tree-sitter.sh <version>     (e.g. 23.1.0)
#
# Why: from 3.0.0 on, `willbooster-tree-sitter-c-sharp` (cccc-cs's grammar)
# emits parse tables with WillBooster's own ABI, which only WillBooster's
# runtime fork `willbooster-tree-sitter` loads. Every other cccc adapter uses
# upstream `tree-sitter`, and the two cannot be linked side by side as is:
#
# - both declare `links = "tree-sitter"`, which cargo allows only once in a
#   dependency graph;
# - both define the same C symbols (`ts_parser_new`, ...), which would collide
#   at link time.
#
# So this script repackages the fork under its own crate name and `links`
# value, and prefixes every global C symbol it defines with `cccc_wb_`: the C
# side through `-D<symbol>=cccc_wb_<symbol>` defines in build.rs (read from
# symbols.txt), the Rust side through `#[link_name]` on the FFI declarations.
# The grammar crate itself references no runtime symbols, so it is used from
# crates.io unchanged.
#
# Needs: curl, tar, perl, python3, a C compiler (`cc`) and `nm`.
# After running it, bump `version` of the cccc-cs dependency on this crate to
# the same version and run the C# tests (crates/cccc-cs and cccc-cli's
# deep_nesting test exercise both runtimes in one binary).
set -eu

if [ $# -ne 1 ]; then
    echo "usage: $0 <willbooster-tree-sitter version>" >&2
    exit 2
fi
version=$1
prefix=cccc_wb_

cd "$(git rev-parse --show-toplevel)"
dest=vendor/willbooster-tree-sitter

work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT

# crates.io rejects requests without a descriptive User-Agent.
curl -fsSL -A "cccc-vendor (https://github.com/moznion/cccc)" \
    "https://crates.io/api/v1/crates/willbooster-tree-sitter/$version/download" |
    tar xzf - -C "$work"
src="$work/willbooster-tree-sitter-$version"

# Versions of the runtime's own dependencies, kept as upstream pins them.
dep_version() {
    perl -0ne 'print $1 if /\[\Q'"$1"'\E\.\Q'"$2"'\E\]\nversion = "([^"]+)"/' "$src/Cargo.toml"
}
lang_version=$(dep_version dependencies tree-sitter-language)
cc_version=$(dep_version build-dependencies cc)
rust_version=$(perl -ne 'print $1 if /^rust-version = "([^"]+)"/' "$src/Cargo.toml")
if [ -z "$lang_version" ] || [ -z "$cc_version" ] || [ -z "$rust_version" ]; then
    echo "error: could not read dependency versions from upstream Cargo.toml" >&2
    exit 1
fi

# Every global symbol the runtime defines, from a build with upstream's flags.
cc_flags="-std=c11 -w -I$src/src -I$src/src/wasm -I$src/include -D_POSIX_C_SOURCE=200112L -D_DEFAULT_SOURCE -D_BSD_SOURCE -D_DARWIN_C_SOURCE"
global_symbols() {
    # Mach-O prepends `_` to C symbol names; ELF does not.
    nm -g --defined-only "$1" | awk 'NF == 3 { print $3 }' |
        if [ "$(uname)" = Darwin ]; then sed 's/^_//'; else cat; fi | sort -u
}
# shellcheck disable=SC2086
cc $cc_flags -c "$src/src/lib.c" -o "$work/plain.o"
global_symbols "$work/plain.o" >"$work/symbols.txt"

# Check that the defines cover every symbol before shipping them.
defines=$(sed "s/.*/-D&=$prefix&/" "$work/symbols.txt")
# shellcheck disable=SC2086
cc $cc_flags $defines -c "$src/src/lib.c" -o "$work/prefixed.o"
if global_symbols "$work/prefixed.o" | grep -v "^$prefix"; then
    echo "error: the symbols above are still unprefixed" >&2
    exit 1
fi

rm -rf "$dest"
mkdir -p "$dest"
cp -R "$src/binding_rust" "$src/src" "$src/include" "$src/LICENSE" "$dest/"
# wasm-only Rust sources stay (dead without the `wasm` feature, dropped below);
# binding_rust/README.md is the crate docs, included by lib.rs.
{
    echo "# Global C symbols of willbooster-tree-sitter $version, renamed to"
    echo "# $prefix<symbol> by build.rs. Generated by"
    echo "# .github/scripts/vendor-willbooster-tree-sitter.sh; do not edit."
    cat "$work/symbols.txt"
} >"$dest/symbols.txt"

python3 -I - "$dest" "$prefix" "$work/symbols.txt" <<'PY'
import pathlib, re, sys

dest, prefix, symbols_file = pathlib.Path(sys.argv[1]), sys.argv[2], sys.argv[3]
symbols = set(pathlib.Path(symbols_file).read_text().split())

# build.rs: rename the symbols, and the static library (its name is what
# `links` resolves to on the linker command line).
build = dest / "binding_rust/build.rs"
text = build.read_text()
old_compile = '        .file(src_path.join("lib.c"))\n        .compile("tree-sitter");'
if old_compile not in text:
    sys.exit("error: build.rs no longer matches the expected compile call")
text = text.replace(
    "    let mut config = cc::Build::new();\n",
    "    let mut config = cc::Build::new();\n"
    "    prefix_symbols(&mut config);\n",
    1,
)
text = text.replace(
    old_compile,
    '        .file(src_path.join("lib.c"))\n        .compile("cccc-willbooster-tree-sitter");',
)
text += f'''
/// Renames every global C symbol of the runtime to `{prefix}<symbol>` so it
/// can be linked next to upstream `tree-sitter`, which defines the same names.
/// The Rust declarations carry the matching `#[link_name]`.
fn prefix_symbols(config: &mut cc::Build) {{
    let manifest_path = PathBuf::from(env::var("CARGO_MANIFEST_DIR").unwrap());
    let symbols_path = manifest_path.join("symbols.txt");
    println!("cargo:rerun-if-changed={{}}", symbols_path.display());
    let symbols = fs::read_to_string(&symbols_path).unwrap();
    for symbol in symbols
        .lines()
        .filter(|line| !line.is_empty() && !line.starts_with('#'))
    {{
        config.define(symbol, Some(format!("{prefix}{{symbol}}").as_str()));
    }}
}}
'''
build.write_text(text)

# Rust FFI declarations: point each renamed function or static at its new name.
decl = re.compile(r"^(\s*)(?:pub(?:\(crate\))?\s+)?(?:fn|static(?:\s+mut)?)\s+(\w+)")
for name in ("bindings.rs", "ffi.rs"):
    path = dest / "binding_rust" / name
    out = []
    for line in path.read_text().split("\n"):
        m = decl.match(line)
        if m and m.group(2) in symbols:
            out.append(f'{m.group(1)}#[link_name = "{prefix}{m.group(2)}"]')
        out.append(line)
    path.write_text("\n".join(out))
PY

cat >"$dest/Cargo.toml" <<EOF
# Generated by .github/scripts/vendor-willbooster-tree-sitter.sh from
# willbooster-tree-sitter $version; regenerate instead of editing by hand.
[package]
name = "cccc-willbooster-tree-sitter"
version = "$version"
edition = "2024"
rust-version = "$rust_version"
license = "MIT"
repository = "https://github.com/moznion/cccc"
description = "WillBooster's tree-sitter runtime fork (willbooster-tree-sitter $version), repackaged with prefixed C symbols so it links next to upstream tree-sitter; used by cccc-cs"
readme = "README.md"
build = "binding_rust/build.rs"
links = "cccc-willbooster-tree-sitter"
include = [
    "/binding_rust/*",
    "/Cargo.toml",
    "/src/*.h",
    "/src/*.c",
    "/src/portable/*",
    "/src/unicode/*",
    "/src/wasm-stdlib/**/*",
    "/include/tree_sitter/api.h",
    "/symbols.txt",
    "/README.md",
    "/LICENSE",
]

[lib]
name = "tree_sitter"
path = "binding_rust/lib.rs"

[features]
default = ["std"]
std = []

[dependencies]
tree-sitter-language = "$lang_version"

[build-dependencies]
cc = "$cc_version"

# Upstream code, kept as is: the \`wasm\` and \`bindgen\` features are dropped
# (their cfgs stay in the source), and its lints are not this workspace's.
[lints.rust]
unexpected_cfgs = { level = "warn", check-cfg = ['cfg(feature, values("wasm", "bindgen"))', "cfg(docsrs)"] }
mismatched_lifetime_syntaxes = "allow"

[lints.clippy]
all = { level = "allow", priority = -1 }
EOF

cat >"$dest/README.md" <<EOF
# cccc-willbooster-tree-sitter

[WillBooster's fork of the tree-sitter runtime](https://github.com/WillBooster/tree-sitter)
(\`willbooster-tree-sitter\` $version), repackaged for
[cccc](https://github.com/moznion/cccc).

\`willbooster-tree-sitter-c-sharp\` 3.0.0 and later only load in this fork, while
every other cccc grammar needs upstream \`tree-sitter\`. Upstream and the fork
both claim \`links = "tree-sitter"\` and define the same C symbols, so they
cannot be linked into one binary as published. This crate is the fork with:

- its own crate name and \`links\` value;
- every global C symbol renamed to \`${prefix}<symbol>\` (see \`symbols.txt\`),
  with matching \`#[link_name]\`s on the Rust side;
- the \`wasm\` and \`bindgen\` features removed.

The Rust API is the fork's, unchanged; its library name is still \`tree_sitter\`.
It is generated by \`.github/scripts/vendor-willbooster-tree-sitter.sh\` in the
cccc repository. It is not meant for use outside cccc.

Licensed under MIT, as upstream (see \`LICENSE\`).
EOF

echo "vendored willbooster-tree-sitter $version into $dest ($(wc -l <"$work/symbols.txt" | tr -d ' ') symbols prefixed)"
